def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize is None:
        return _lru_cache_wrapper(None, typed)
    elif not isinstance(maxsize, int):
        raise TypeError('Expected maxsize to be an integer or None')
    return _lru_cache_wrapper(maxsize, typed)

def _lru_cache_wrapper(maxsize, typed):
    def decorator(func):
        from collections import OrderedDict
        from functools import wraps
        from threading import RLock

        cache = OrderedDict()
        cache_get = cache.get
        cache_len = len
        cache_popitem = cache.popitem
        cache_clear = cache.clear
        cache_move_to_end = cache.move_to_end
        lock = RLock()
        hits = misses = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            if typed:
                key = (args, frozenset(kwargs.items()))
            else:
                key = (args, frozenset(kwargs.items()))
            with lock:
                try:
                    value = cache_get(key)
                except TypeError:
                    # unhashable arguments
                    return func(*args, **kwargs)
                else:
                    if value is not None:
                        cache_move_to_end(key)
                        hits += 1
                        return value
            value = func(*args, **kwargs)
            with lock:
                if maxsize is not None:
                    if cache_len(cache) >= maxsize:
                        cache_popitem(last=False)
                cache[key] = value
                misses += 1
            return value

        def cache_info():
            with lock:
                return {'hits': hits, 'misses': misses, 'maxsize': maxsize, 'currsize': cache_len(cache)}

        def cache_clear():
            with lock:
                cache_clear()
                nonlocal hits, misses
                hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorator
