import re
def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:
        # POSIX-like splitting
        # Handle quotes and escapes
        result = []
        current = []
        in_single = False
        in_double = False
        escape = False
        for char in s:
            if escape:
                current.append(char)
                escape = False
            elif char == '\\' and not in_single:
                escape = True
            elif char == "'" and not in_double:
                in_single = not in_single
            elif char == '"' and not in_single:
                in_double = not in_double
            elif char.isspace() and not in_single and not in_double:
                if current:
                    result.append(''.join(current))
                    current = []
            else:
                current.append(char)
        if current:
            result.append(''.join(current))
        return result
    elif platform == 0:
        # Windows/CMD splitting
        # Use a regex approach for Windows command line parsing
        # This is a simplified version; Windows command line parsing is complex
        # We'll use a regex that handles quoted strings and unquoted tokens
        # Pattern: match either a quoted string (with possible escaped quotes) or a sequence of non-whitespace characters
        pattern = r'(?:"((?:\\.|[^"\\])*)"|(\S+))'
        matches = re.finditer(pattern, s)
        result = []
        for match in matches:
            if match.group(1) is not None:
                # Quoted string, unescape backslashes
                result.append(match.group(1).replace('\\"', '"').replace('\\\\', '\\'))
            else:
                result.append(match.group(2))
        return result
    else:
        raise ValueError(f"Unknown platform: {platform}")

