def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try to parse as JSON first
    try:
        data = json.loads(document)
        # Check if it's a valid webfinger JSON response
        if "links" in data:
            return data
    except json.JSONDecodeError:
        pass

    # Try to parse as XRD (XML)
    try:
        root = ET.fromstring(document)
        # XRD format: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd">
        # We need to handle namespaces
        namespace = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd'}

        # Extract subject
        subject_elem = root.find('xrd:subject', namespace)
        subject = subject_elem.text if subject_elem is not None else None

        # Extract links
        links = []
        for link_elem in root.findall('xrd:link', namespace):
            link = {}
            for attr in ['rel', 'href', 'type']:
                if attr in link_elem.attrib:
                    link[attr] = link_elem.attrib[attr]
            links.append(link)

        result = {
            "subject": subject,
            "links": links
        }
        return result
    except ET.ParseError:
        pass

    # If neither format works, return an empty dict or raise an error
    return {}
